import {typeData} from './types.mjs';
// The single recommendation and validation engine used by web and Discord.
export const total=v=>v.reduce((a,b)=>a+Number(b||0),0);
export const validEV=v=>Array.isArray(v)&&v.length===6&&v.every(x=>Number.isInteger(x)&&x>=0&&x<=32)&&total(v)<=66;
export const evText=v=>'HABCDS'.split('').map((k,i)=>k+String(v[i]??0).padStart(2,'0')).join(' ');
export function calculateStats(base,evs,nature){const keys=['hp','atk','def','spa','spd','spe'],up=nature?.[2],down=nature?.[3];return base.map((b,i)=>{const raw=Number(b)+(i?20:75)+Number(evs[i]||0);if(i===0)return raw;return Math.floor(raw*(keys[i]===up?1.1:keys[i]===down?0.9:1))})}
export function damageRolls(power,attack,defense,modifier=1){if(![power,attack,defense,modifier].every(Number.isFinite)||power<=0||attack<=0||defense<=0||modifier<0)return [];if(modifier===0)return Array(15).fill(0);const base=Math.floor(Math.floor((22*power*attack/defense))/50)+2;return Array.from({length:15},(_,i)=>Math.max(1,Math.floor(base*modifier*(86+i)/100)))}
export function classifyKO(damage,hp){if(!damage.length||!Number.isFinite(hp)||hp<=0)return null;const min=Math.min(...damage),max=Math.max(...damage),pct=n=>Math.round(n*1000/hp)/10,chance1=damage.filter(x=>x>=hp).length/damage.length;if(max===0)return {label:'효과 없음',chance:0,min,max,minPct:0,maxPct:0};if(min>=hp)return {label:'확정 1타',chance:100,min,max,minPct:pct(min),maxPct:pct(max)};if(max>=hp)return {label:`난수 1타 ${Math.round(chance1*100)}%`,chance:chance1*100,min,max,minPct:pct(min),maxPct:pct(max)};for(let hits=2;hits<=3;hits++){let sums=[0];for(let i=0;i<hits;i++)sums=sums.flatMap(a=>damage.map(b=>a+b));const chance=sums.filter(x=>x>=hp).length/sums.length;if(chance===1)return {label:`확정 ${hits}타`,chance:100,min,max,minPct:pct(min),maxPct:pct(max)};if(chance>0)return {label:`난수 ${hits}타 ${Math.round(chance*100)}%`,chance:chance*100,min,max,minPct:pct(min),maxPct:pct(max)}}return {label:'확정 4타 이상',chance:0,min,max,minPct:pct(min),maxPct:pct(max)}}
export function itemPower(item,moveType,category,master){const d=master.items.find(x=>x[0]===item)?.[2]||'';if(item==='생명의구슬')return 1.3;if(category==='물리'&&d.includes('물리 기술의 위력이 1.1배'))return 1.1;if(category==='특수'&&d.includes('특수 기술의 위력이 1.1배'))return 1.1;if(d.includes(moveType+'타입 기술의 위력이 1.2배'))return 1.2;return 1}
export function abilityPower(ability,moveType,category,master){const d=master.abilities.find(x=>x[0]===ability)?.[2]||'';if(category==='물리'&&d.includes('물리 기술의 위력이 2배'))return 2;const m=d.match(new RegExp(moveType+'타입 기술의 위력이 ([\\d.]+)배'));return m&&!/HP가|상태일 때|되면/.test(d)?Number(m[1]):1}
export function battleCalculation(attacker,defender,set,move,defenderEvs,master){const atkBase=master.pokemon.find(p=>p[0]===attacker.name)?.slice(3,9).map(Number),defBase=master.pokemon.find(p=>p[0]===defender.name)?.slice(3,9).map(Number),nature=master.natures.find(x=>x[0]===set.natures);if(!atkBase||!defBase||!move||move[3]==='변화'||Number(move[4])<=0||!validEV(set.evs)||!validEV(defenderEvs))return null;const attackerStats=calculateStats(atkBase,set.evs,nature),defenderStats=calculateStats(defBase,defenderEvs,null),type=koreanType[move[2]]||move[2],category=move[3],attack=category==='물리'?attackerStats[1]:attackerStats[3],defense=category==='물리'?defenderStats[2]:defenderStats[4],stab=attacker.types.includes(type)?(set.abilities==='적응력'?2:1.5):1,typeMultiplier=multiplier(type,defender.types),itemMultiplier=itemPower(set.items,type,category,master),abilityMultiplier=abilityPower(set.abilities,type,category,master),modifier=stab*typeMultiplier*itemMultiplier*abilityMultiplier,damage=damageRolls(Number(move[4]),attack,defense,modifier),result=classifyKO(damage,defenderStats[0]),powerIndex=Math.round(attack*Number(move[4])*stab*itemMultiplier*abilityMultiplier);return {attackerStats,defenderStats,type,category,attack,defense,stab,typeMultiplier,itemMultiplier,abilityMultiplier,modifier,damage,result,powerIndex,physicalBulk:Math.round(attackerStats[0]*attackerStats[2]),specialBulk:Math.round(attackerStats[0]*attackerStats[4]),speed:Math.floor(attackerStats[5]*(set.items==='구애스카프'?1.5:1))}}
export const defenseScenarios=[{key:'h0b0',label:'H0 B0',evs:[0,0,0,0,0,0]},{key:'h32b0',label:'H32 B0',evs:[32,0,0,0,0,0]},{key:'h32b32',label:'H32 B32',evs:[32,0,32,0,0,0]},{key:'h0b32',label:'H0 B32',evs:[0,0,32,0,0,0]},{key:'h32d0',label:'H32 D0',evs:[32,0,0,0,0,0]},{key:'h32d32',label:'H32 D32',evs:[32,0,0,0,32,0]},{key:'h0d32',label:'H0 D32',evs:[0,0,0,0,32,0]}];
export function strongestStatMove(attacker,defender,set,master,limit=4){return attacker.moves.slice(0,limit).map(record=>{const move=master.moves.find(m=>m[0]===record.name),calc=battleCalculation(attacker,defender,set,move,[0,0,0,0,0,0],master);return calc?{move,rate:record.rate,calc}:null}).filter(Boolean).sort((a,b)=>b.calc.result.maxPct-a.calc.result.maxPct||b.rate-a.rate)[0]||null}
export function damageScenarioResults(attacker,defender,set,move,master){return defenseScenarios.map(s=>({...s,calc:battleCalculation(attacker,defender,set,move,s.evs,master)}))}
export function speedVariants(pokemon,master){const base=master.pokemon.find(p=>p[0]===pokemon.name)?.slice(3,9).map(Number),fastNature=master.natures.find(n=>n[2]==='spe');if(!base||!fastNature)return null;const neutral0=calculateStats(base,[0,0,0,0,0,0],null)[5],neutral32=calculateStats(base,[0,0,0,0,0,32],null)[5],fast32=calculateStats(base,[0,0,0,0,0,32],fastNature)[5];return [{key:'fast',label:'최속 (S32·상승성격)',value:fast32},{key:'neutral32',label:'준속 (S32·무보정)',value:neutral32},{key:'neutral0',label:'무보정 (S0)',value:neutral0},{key:'scarfFast',label:'스카프 최속',value:Math.floor(fast32*1.5)},{key:'scarfNeutral32',label:'스카프 준속',value:Math.floor(neutral32*1.5)},{key:'scarfNeutral0',label:'스카프 무보정',value:Math.floor(neutral0*1.5)}]}
export function makeSet(p,used=[]){return {name:p.name,items:p.items.find(i=>!used.includes(i.name))?.name||'',abilities:p.abilities[0]?.name||'',natures:p.natures[0]?.name||'',moves:p.moves.slice(0,4).map(x=>x.name),evs:(p.evs[0]?.name.match(/\d+/g)||[]).map(Number)}}
export function validSet(s,rows,master=null){const p=s&&rows.find(p=>p.name===s.name),allowed=k=>new Set((master?.[k]||p?.[k]||[]).map(x=>Array.isArray(x)?x[0]:x.name));return !!p&&['items','abilities','natures'].every(k=>s[k]===''||allowed(k).has(s[k]))&&Array.isArray(s.moves)&&s.moves.length<=4&&new Set(s.moves).size===s.moves.length&&s.moves.every(n=>allowed('moves').has(n))&&validEV(s.evs)}
export function recommend(rows,open,selected,master=null,sets=[]){return rows.filter(p=>!selected.includes(p.name)).map(p=>{const teammateEvidence=selected.map(n=>{const member=rows.find(r=>r.name===n),direct=member?.teammates.indexOf(p.name)??-1,reverse=p.teammates.indexOf(n);return direct>=0||reverse>=0?{name:n,direct:direct>=0?direct+1:null,reverse:reverse>=0?reverse+1:null}:null}).filter(Boolean),linked=teammateEvidence.map(x=>x.name),co=open?open.teams.filter(t=>t.team.some(m=>m.name===p.name)&&selected.some(n=>t.team.some(m=>m.name===n))).length:0;const assessment=assessCandidate(p,rows,open,selected,master,sets),support=Math.min(20,teammateEvidence.reduce((a,x)=>a+(x.direct?Math.max(1,6-x.direct/2):0)+(x.reverse?Math.max(1,4-x.reverse/3):0),0)+Math.log2(co+1)),score=assessment.defense+assessment.meta+assessment.empirical.score-assessment.penalty+support+1/Math.sqrt(p.rank);return {p,linked,teammateEvidence,co,score,assessment}}).sort((a,b)=>b.score-a.score)}
export function draft(rows,open,selected=[],master=null){let result=[];for(const n of selected){const p=rows.find(p=>p.name===n);if(!p)throw Error('첨부 통계에 없는 포켓몬입니다.');result.push(makeSet(p,result.map(s=>s.items)))}while(result.length<6){const next=recommend(rows,open,result.map(s=>s.name),master,result).find(({p})=>p.items.length&&p.abilities.length&&p.natures.length&&p.moves.length>=4&&p.evs.length);if(!next)break;result.push(makeSet(next.p,result.map(s=>s.items)))}return result}

export const koreanType={Normal:'노말',Fire:'불꽃',Water:'물',Electric:'전기',Grass:'풀',Ice:'얼음',Fighting:'격투',Poison:'독',Ground:'땅',Flying:'비행',Psychic:'에스퍼',Bug:'벌레',Rock:'바위',Ghost:'고스트',Dragon:'드래곤',Dark:'악',Steel:'강철',Fairy:'페어리'};
export function multiplier(attack,defenses){if(!typeData.chart[attack]||!defenses?.length||defenses.some(t=>typeData.chart[attack][t]===undefined))return Number.NaN;return defenses.reduce((a,t)=>a*typeData.chart[attack][t],1)}
const moveCache=new WeakMap(),attackCache=new WeakMap();
export function attacks(p,master,set){if(!master)return [];if(!set&&attackCache.has(p))return attackCache.get(p);if(!moveCache.has(master))moveCache.set(master,new Map(master.moves.map(m=>[m[0],m])));const selected=set?.moves||p.moves.slice(0,4).map(v=>v.name);const result=selected.map(n=>{const m=moveCache.get(master).get(n),record=p.moves.find(x=>x.name===n);return m&&m[3]!=='변화'&&Number(m[4])>0?{name:n,type:koreanType[m[2]]||m[2],rate:record?.rate||0,power:Number(m[4]),category:m[3]}:null}).filter(Boolean);if(!set)attackCache.set(p,result);return result}
export function matchup(p,target,master,set){const choices=attacks(p,master,set).map(m=>({...m,multiplier:multiplier(m.type,target.types)})).sort((a,b)=>b.multiplier-a.multiplier||b.rate-a.rate);const incoming=attacks(target,master).map(m=>({...m,multiplier:multiplier(m.type,p.types)})).sort((a,b)=>b.multiplier-a.multiplier);return {attack:choices[0]||null,incoming:incoming[0]||null,usable:!!choices[0]&&!!incoming[0]&&choices[0].multiplier>=2&&incoming[0].multiplier<=1}}
export function teamTypeSummary(rows,selected){const members=selected.map(n=>rows.find(p=>p.name===n)).filter(Boolean);return Object.keys(typeData.chart).map(type=>({type,weak:members.filter(p=>multiplier(type,p.types)>=2).map(p=>p.name),resist:members.filter(p=>multiplier(type,p.types)<=.5).map(p=>p.name),four:members.filter(p=>multiplier(type,p.types)>=4).map(p=>p.name)}))}
// The source counter column lists opponents that defeated the row Pokemon.
// Reverse lookup therefore gives observed evidence that a candidate defeated a threat.
export function empiricalCoverage(p,rows,open,selected){const byName=new Map(rows.map(x=>[x.name,x])),meta=new Map((open?.frequency||[]).map(x=>[x.name,x.rate]));const threats=new Map();for(const name of selected){const member=byName.get(name);for(const c of member?.counters||[]){const previous=threats.get(c.name),priority=(1+(meta.get(c.name)||0)/10)*(c.rate/100)*Math.min(1,Math.log10(c.n+1)/3);if(!previous)threats.set(c.name,{name:c.name,targets:[name],rate:c.rate,n:c.n,priority});else{if(!previous.targets.includes(name))previous.targets.push(name);previous.priority+=priority;previous.rate=Math.max(previous.rate,c.rate);previous.n=Math.max(previous.n,c.n)}}}const pool=[...threats.values()].sort((a,b)=>b.priority-a.priority),covered=[];for(const threat of pool){const evidence=(byName.get(threat.name)?.counters||[]).find(c=>c.name===p.name);if(evidence)covered.push({...threat,evidence})}const totalWeight=pool.reduce((a,x)=>a+x.priority,0)||1,coveredWeight=covered.reduce((a,x)=>a+x.priority,0);return {threats:pool,covered,score:25*coveredWeight/totalWeight}}
export function assessCandidate(p,rows,open,selected,master,sets=[]){const summary=teamTypeSummary(rows,selected),repaired=summary.filter(s=>s.weak.length&&s.resist.length===0&&multiplier(s.type,p.types)<=.5),added=summary.filter(s=>s.weak.length&&s.resist.length===0&&multiplier(s.type,p.types)>=2);const pool=(open?.frequency||rows.slice(0,20).map(p=>({name:p.name,rate:100/Math.sqrt(p.rank)}))).slice(0,20).map(f=>({...f,p:rows.find(p=>p.name===f.name)})).filter(f=>f.p);let totalWeight=pool.reduce((a,t)=>a+t.rate,0)||1;let gains=[];
for(const t of pool){const before=selected.some(n=>{const member=rows.find(x=>x.name===n);return member&&matchup(member,t.p,master,sets.find(s=>s.name===n)).usable});const m=matchup(p,t.p,master);if(!before&&m.usable)gains.push({name:t.name,rate:t.rate,...m})}
const defense=Math.min(30,repaired.reduce((a,s)=>a+8+Math.max(0,s.weak.length-1)*4,0));const metaScore=30*gains.reduce((a,t)=>a+t.rate,0)/totalWeight,empirical=empiricalCoverage(p,rows,open,selected);const penalty=Math.min(30,added.reduce((a,s)=>a+4*s.weak.length,0));return {repaired,gains,added,defense,meta:metaScore,empirical,penalty}}
